"use strict";
window.ESP3_MASCOTS = Object.freeze({
  "neutral": "data:image/webp;base64,",
  "flower": "data:image/webp;base64,",
  "heart": "data:image/webp;base64,",
  "mustache": "data:image/webp;base64,",
  "sideeye": "data:image/webp;base64,",
  "angry": "data:image/webp;base64,"
});
for (const image of document.querySelectorAll("[data-mascot]")) image.src = window.ESP3_MASCOTS[image.dataset.mascot];
